// Scratch check of _unlocal_date (old vs new) under the TZ this process runs in.
// Inputs mirror what date_picker.ts receives:
//   (a) a number: Python serializes datetime.date(2019,9,20) as ms since epoch at 00:00 UTC
//   (b) a string: after a pick, model.value is date.toDateString(), e.g. "Mon Sep 16 2019"
function oldUnlocal(date) {
  const datestr = date.toISOString().substr(0, 10)
  const tup = datestr.split('-')
  return new Date(Number(tup[0]), Number(tup[1]) - 1, Number(tup[2]))
}
function newUnlocal(date) {
  const timeOffsetInMS = date.getTimezoneOffset() * 60000
  date.setTime(date.getTime() - timeOffsetInMS)
  const datestr = date.toISOString().substr(0, 10)
  const tup = datestr.split('-')
  return new Date(Number(tup[0]), Number(tup[1]) - 1, Number(tup[2]))
}
const fmt = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
const pyDateMs = Date.UTC(2019, 8, 20)            // datetime.date(2019, 9, 20) from Python
const pickedStr = "Mon Sep 16 2019"               // toDateString() after a pick
const cases = [["number(py date 2019-09-20)", () => new Date(pyDateMs), "2019-09-20"],
               ["string(toDateString Sep 16)", () => new Date(pickedStr), "2019-09-16"]]
console.log(`TZ=${process.env.TZ || '(unset)'} offset(min)=${new Date(pyDateMs).getTimezoneOffset()}`)
for (const [name, mk, want] of cases) {
  const o = fmt(oldUnlocal(mk())), n = fmt(newUnlocal(mk()))
  console.log(`  ${name.padEnd(30)} want=${want} old=${o}${o === want ? '' : ' (WRONG)'} new=${n}${n === want ? '' : ' (WRONG)'}`)
}

